import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import axios from 'axios';
import './Resources.css';
import './ProductOverview.css'; // Navigation Styles

const ResearchPage = () => {
  // --- UI STATES ---
  const [activeTab, setActiveTab] = useState('overview');
  
  // --- NAV STATES ---
  const [activeCategory, setActiveCategory] = useState('Air Quality');
  const [isMegaMenuOpen, setIsMegaMenuOpen] = useState(false);
  const [isSolutionsMenuOpen, setIsSolutionsMenuOpen] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // --- DYNAMIC DATA STATES (Only for Training & Brochures) ---
  const [brochures, setBrochures] = useState([]);
  const [workshops, setWorkshops] = useState([]);
  const API_BASE_URL = 'https://aiiot-1.onrender.com';

  // --- FETCH DYNAMIC DATA ---
  useEffect(() => {
    const fetchData = async () => {
      try {
        // 1. Fetch Workshops (Dynamic)
        const workshopRes = await axios.get(`${API_BASE_URL}/api/workshops/`);
        const workshopData = Array.isArray(workshopRes.data) ? workshopRes.data : workshopRes.data.results || [];
        setWorkshops(workshopData);

        // 2. Fetch Brochures (Dynamic)
        const brochureRes = await axios.get(`${API_BASE_URL}/api/brochures/`);
        const brochureData = Array.isArray(brochureRes.data) ? brochureRes.data : brochureRes.data.results || [];
        // Only show active brochures
        setBrochures(brochureData.filter(b => b.is_active));

      } catch (error) {
        console.error('Error fetching dynamic data:', error);
      }
    };
    fetchData();
  }, []);

  // --- STATIC DATA (Hardcoded as requested) ---
  const publications = [
    { type: 'Conference Paper', title: 'Comparative Analysis of RNN models for Air Pollution Forecasting', venue: 'ICICDS-2025', status: 'Published' },
    { type: 'Research Paper', title: 'A Comparative Analysis of Conventional Methods for Sensor-Driven Spatial Interpolation', venue: 'Eng. Tech & Applied Science Research', status: 'Communicated' },
    { type: 'Conference Paper', title: 'AI-Based Environmental Pollution Monitoring with Personalized Health Risk Assessment', venue: 'ICSSAI-2025 (Kolkata)', status: 'Accepted' }
  ];

  const patent = {
    title: 'AI Integrated Water Level Monitoring Solution with Flood Alerts',
    appNumber: '202441079490',
    filingDate: 'October 25, 2024',
    status: 'Filed with INDIA Patent Office'
  };

  const objectives = [
    "Develop intelligent sensor modules for pollution monitoring.",
    "Validate smart water level monitoring with flood alerts.",
    "Create digital systems for water level distribution.",
    "Build a startup & skill development ecosystem.",
    "Develop Explainable AI (XAI) analysis software for IoT."
  ];

  // --- STATIC NAV DATA ---
  const solutionsList = [
    { name: 'Air Quality Monitoring', link: '/project/intelligent-sensor' },
    { name: 'Flood Alert System', link: '/project/water-level' },
    { name: 'Digital Water Distribution', link: '/project/digital-water' },
    { name: 'Startup & Skill Development', link: '/project/startup-skill' }
  ];

  const productMenuData = {
    'Air Quality': {
      title: 'Air Quality Monitoring',
      description: 'Precision sensors for indoor and outdoor environments.',
      items: [
        { name: 'Indoor Monitor', image: '/sensor_modules/aqicrop.jpeg', link: '/product-details/indoor-monitor' },
        { name: 'Outdoor Station', image: '/sensor_modules/aqi1.jpeg', link: '/product-details/outdoor-station' },
        { name: 'Gas Sensors', image: 'https://images.unsplash.com/photo-1621905252507-b35492cc74b4?w=400', link: '/product-details/gas-sensors' }
      ]
    },
    'Water Solutions': {
      title: 'Water Management',
      description: 'Flood alerts and distribution logic.',
      items: [
        { name: 'Smart Flood Alert System', image: '/sensor_modules/river1.jpg', link: '/product-details/flood-alert' },
        { name: 'Digital Flow Meter', image: '/sensor_modules/distribution.jpeg', link: '/product-details/distribution-net' }
      ]
    },
    'Weather': {
      title: 'Weather Stations',
      description: 'Hyper-local weather data collection.',
      items: [
        { name: 'AWS v1 & v2', image: '/sensor_modules/weather.jpg', link: '/product-details/weather-station' },
        { name: 'Rain Gauges', image: 'https://images.unsplash.com/photo-1590055531860-6902633df018?w=400', link: '/product-details/rain-gauge' }
      ]
    },
    'Training': {
      title: 'Skill Development',
      description: 'Kits and workshops for students.',
      items: [
        { name: 'IoT Workshops & Internships', image: '/sensor_modules/skill.jpg', link: '/product-details/iot-training' },
        { name: 'PCB Design Course', image: 'https://images.unsplash.com/photo-1517048676732-d65bc937f952?w=400', link: '/product-details/pcb-workshop' }
      ]
    }
  };

  return (
    <div className="resources-page-container">
      
      {/* HEADER */}
      <nav className="aiiot-header-local">
        <div className="nav-container-inner">
           <Link to="/" style={{ textDecoration: 'none' }}>
             <span className="logo-text">AI-IoT<span style={{color:'#2563eb'}}>Lab</span></span>
           </Link>
           <div className="desktop-nav" style={{ display: 'flex', alignItems: 'center' }}>
             <Link to="/" className="nav-link">Home</Link>
             
             {/* Solutions Dropdown */}
             <div className="dropdown-wrapper" onMouseEnter={() => setIsSolutionsMenuOpen(true)} onMouseLeave={() => setIsSolutionsMenuOpen(false)}>
                 <div className="nav-link product-trigger" style={{ cursor: 'pointer' }}>Solutions <span>▾</span></div>
                 <div className={`simple-dropdown ${isSolutionsMenuOpen ? 'visible' : ''}`}>
                   {solutionsList.map((sol, index) => (
                     <Link key={index} to={sol.link} className="simple-dropdown-item">{sol.name}</Link>
                   ))}
                 </div>
             </div>

             <div className="mega-menu-wrapper" onMouseEnter={() => setIsMegaMenuOpen(true)} onMouseLeave={() => setIsMegaMenuOpen(false)}>
                 <Link to="/products" className="nav-link product-trigger">Products <span>▾</span></Link>
                 <div className={`mega-menu-container ${isMegaMenuOpen ? 'visible' : ''}`}>
                   <div className="mega-menu-sidebar">
                     {Object.keys(productMenuData).map((key) => (
                       <div key={key} className={`mega-sidebar-item ${activeCategory === key ? 'active' : ''}`} onMouseEnter={() => setActiveCategory(key)}>
                         {key} <span>›</span>
                       </div>
                     ))}
                   </div>
                   <div className="mega-menu-content">
                     <div className="mega-content-header">
                       <h4>{productMenuData[activeCategory].title}</h4>
                       <p>{productMenuData[activeCategory].description}</p>
                     </div>
                     <div className="mega-grid">
                       {productMenuData[activeCategory].items.map((item, idx) => (
                         <Link to={item.link} key={idx} className="mega-product-card">
                            <div className="mega-img-box"><img src={item.image} alt={item.name} /></div>
                            <span>{item.name}</span>
                         </Link>
                       ))}
                     </div>
                   </div>
                 </div>
             </div>
             
             <Link to="/resources" className="nav-link active">R&D Center</Link>
             <a href="#contact" className="btn-primary-small" style={{marginLeft:'2rem'}}>Contact</a>
           </div>

           <button className="mobile-nav-toggle" onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}>☰</button>
        </div>
        
        {isMobileMenuOpen && (
            <div className="mobile-menu-wrapper">
                <Link to="/" onClick={() => setIsMobileMenuOpen(false)} className="mobile-link">Home</Link>
                <Link to="/resources" onClick={() => setIsMobileMenuOpen(false)} className="mobile-link">R&D Center</Link>
            </div>
         )}
      </nav>

      <div className="resources-content-wrapper">
        
        {/* HERO SECTION */}
        <section className="resources-hero-section reveal-on-scroll">
          <span className="hero-badge">Research & Development Wing</span>
          <h1 className="page-title">Innovating the <span className="text-gradient">Edge</span></h1>
          <p className="page-intro">
            Advanced prototyping, sensor fusion, and digital networking for next-generation smart city infrastructure.
          </p>

          {/* STATIC OBJECTIVES */}
          <div className="objectives-grid">
             {objectives.map((obj, i) => (
                <div key={i} className="objective-card reveal-on-scroll delay-100">
                   <p style={{ margin: 0, fontWeight: 500, fontSize: '0.95rem' }}>
                     <span className="check-icon">❯</span> {obj}
                   </p>
                </div>
             ))}
          </div>
        </section>

        {/* TABS NAVIGATION */}
        <div className="research-tabs">
            <button className={`tab-btn ${activeTab === 'overview' ? 'active' : ''}`} onClick={() => setActiveTab('overview')}>Overview</button>
            <button className={`tab-btn ${activeTab === 'training' ? 'active' : ''}`} onClick={() => setActiveTab('training')}>Training & Workshops</button>
            <button className={`tab-btn ${activeTab === 'downloads' ? 'active' : ''}`} onClick={() => setActiveTab('downloads')}>Brochures</button>
        </div>

        {/* --- TAB: OVERVIEW (Static + Hardcoded) --- */}
        {activeTab === 'overview' && (
            <div>
                <div className="section-header reveal-on-scroll">
                    <div>
                        <h2 className="section-title">Intellectual Property</h2>
                        <span className="section-subtitle">Patents & Publications</span>
                    </div>
                </div>

                <div className="tech-grid">
                    {/* Hardcoded Patent */}
                    <div className="tech-card patent-card reveal-on-scroll delay-100">
                        <div style={{display:'flex', justifyContent:'space-between'}}>
                            <span className="status-badge badge-filed">Patent Application</span>
                            <span style={{fontSize:'1.2rem'}}>📜</span>
                        </div>
                        <h3 className="card-title">{patent.title}</h3>
                        <div className="card-meta">
                        <div style={{display:'flex', gap:'1rem'}}>
                            <div><strong>ID:</strong> {patent.appNumber}</div>
                            <div><strong>Date:</strong> {patent.filingDate}</div>
                        </div>
                        </div>
                        <div className="card-footer">
                        <span>STATUS</span>
                        <span style={{color:'#c2410c'}}>{patent.status}</span>
                        </div>
                    </div>

                    {/* Hardcoded Publications */}
                    {publications.map((pub, idx) => (
                        <div key={idx} className="tech-card pub-card reveal-on-scroll delay-200">
                            <span className={`status-badge ${pub.status === 'Published' || pub.status === 'Accepted' ? 'badge-success' : 'badge-pending'}`}>
                                {pub.status}
                            </span>
                            <h3 className="card-title">{pub.title}</h3>
                            <div className="card-meta">
                                {pub.venue}
                            </div>
                            <div className="card-footer">
                                <span>TYPE</span>
                                <span>{pub.type}</span>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        )}

        {/* --- TAB: TRAINING (DYNAMIC FROM BACKEND) --- */}
        {activeTab === 'training' && (
            <div className="clean-table-wrapper reveal-on-scroll">
                <h3 style={{padding:'1.5rem', margin:0, borderBottom:'1px solid #e2e8f0'}}>Upcoming & Past Events</h3>
                {workshops.length === 0 ? (
                    <div style={{padding:'3rem', textAlign:'center', color:'#64748b'}}>
                        <p>No workshops scheduled in the system.</p>
                        <small>Please add WorkshopEvents in Django Admin.</small>
                    </div>
                ) : (
                    <table className="clean-table">
                        <thead>
                            <tr>
                                <th style={{width:'35%'}}>Program</th>
                                <th>Type</th>
                                <th>Date</th>
                                <th>Participants</th>
                            </tr>
                        </thead>
                        <tbody>
                            {workshops.map((ev, i) => (
                                <tr key={i}>
                                    <td style={{ fontWeight: 600 }}>{ev.title}</td>
                                    <td><span style={{ background: '#f1f5f9', padding: '4px 8px', borderRadius: '4px', fontSize: '0.75rem', fontFamily:'var(--font-mono)', textTransform:'uppercase' }}>{ev.category}</span></td>
                                    <td>{ev.event_date_text}</td>
                                    <td>{ev.participants}</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                )}
            </div>
        )}

        {/* --- TAB: DOWNLOADS (DYNAMIC FROM BACKEND) --- */}
        {activeTab === 'downloads' && (
            <div>
                <h2 className="section-title" style={{marginBottom:'2rem'}}>Downloads & Resources</h2>
                {brochures.length === 0 ? (
                    <div style={{textAlign:'center', color:'#64748b', padding:'3rem', background:'white', borderRadius:'12px', border:'1px solid #e2e8f0'}}>
                        <p>No documents available.</p>
                        <small>Please upload Brochures in Django Admin and check "Is active".</small>
                    </div>
                ) : (
                    <div className="brochure-grid">
                        {brochures.map((b, idx) => (
                            <div key={idx} className="brochure-item reveal-on-scroll">
                                <div style={{display:'flex', justifyContent:'space-between', alignItems:'flex-start'}}>
                                    <div className="icon-box">📄</div>
                                    <span style={{fontSize:'0.7rem', color:'#94a3b8', border:'1px solid #e2e8f0', padding:'2px 6px', borderRadius:'4px', textTransform:'uppercase'}}>{b.category}</span>
                                </div>
                                <div className="brochure-title">{b.title}</div>
                                <div style={{ fontSize: '0.85rem', color: '#64748b', lineHeight: 1.5, marginBottom:'1rem' }}>{b.description}</div>
                                <a href={b.file.startsWith('http') ? b.file : `${API_BASE_URL}${b.file}`} target="_blank" rel="noopener noreferrer" className="download-text">
                                    Download Document <span>↓</span>
                                </a>
                            </div>
                        ))}
                    </div>
                )}
            </div>
        )}

      </div>
    </div>
  );
};

export default ResearchPage;
